import{_ as a,a0 as o,w as d,s as p,I as s,x as t,a1 as l,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"MidnightBSD：或許是你通往 FreeBSD 的大門 | LCTT x X-CMD","titleTemplate":false,"description":"MidnightBSD：或許是你通往 FreeBSD 的大門 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"MidnightBSD：或許是你通往 FreeBSD 的大門 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"MidnightBSD：或許是你通往 FreeBSD 的大門 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD","title":"MidnightBSD：或許是你通往 FreeBSD 的大門","tag":"202002","desc":""},"relativePath":"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD.md","filePath":"[post].md"}'),g={name:"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD.md"};function h(u,i,b,f,k,m){const e=o("Link");return d(),p("div",null,[i[29]||(i[29]=s("h1",{id:"midnightbsd-或許是你通往-freebsd-的大門",tabindex:"-1"},[t("MidnightBSD：或許是你通往 FreeBSD 的大門 "),s("a",{class:"header-anchor",href:"#midnightbsd-或許是你通往-freebsd-的大門","aria-label":"Permalink to “MidnightBSD：或許是你通往 FreeBSD 的大門”"},"​")],-1)),i[30]||(i[30]=s("p",null,[s("img",{src:"https://www.linux.com/wp-content/uploads/2019/08/midnight_4_0.jpg",alt:""})],-1)),s("p",null,[l(e,{href:"https://www.freebsd.org/"},{default:n(()=>[...i[0]||(i[0]=[t("FreeBSD",-1)])]),_:1}),i[4]||(i[4]=t(" 是一個開源操作系統，衍生自著名的 ",-1)),s("ruby",null,[l(e,{href:"https://en.wikipedia.org/wiki/Berkeley_Software_Distribution"},{default:n(()=>[...i[1]||(i[1]=[t("伯克利軟件套件",-1)])]),_:1}),i[2]||(i[2]=s("rt",null,"Berkeley Software Distribution",-1))]),i[5]||(i[5]=t("（BSD）。FreeBSD 的第一個版本發佈於 1993 年，並且仍然在繼續發展。2007 年左右，Lucas Holt 想要利用 OpenStep（現在是 Cocoa）的 Objective-C 框架、widget 工具包和應用程序開發工具的 ",-1)),l(e,{href:"https://en.wikipedia.org/wiki/GNUstep"},{default:n(()=>[...i[3]||(i[3]=[t("GnuStep",-1)])]),_:1}),i[6]||(i[6]=t(" 實現，來創建一個 FreeBSD 的分支。為此，他開始開發 MidnightBSD 桌面發行版。",-1))]),i[31]||(i[31]=s("p",null,"MidnightBSD（以 Lucas 的貓 Midnight 命名）仍然在積極地（儘管緩慢）開發。從 2017 年 8 月開始，可以獲得最新的穩定發佈版本（0.8.6）（LCTT 譯註：截止至本譯文發佈時，當前是 2019/10/31 發佈的 1.2 版）。儘管 BSD 發行版不是你所説的用户友好型發行版，但上手安裝是熟悉如何處理 文本（ncurses）安裝過程以及通過命令列完成安裝的好方法。",-1)),i[32]||(i[32]=s("p",null,"這樣，你最終會得到一個非常可靠的 FreeBSD 分支的桌面發行版。這需要花費一點精力，但是如果你是一名正在尋找擴展你的技能的 Linux 用户……這是一個很好的起點。",-1)),i[33]||(i[33]=s("p",null,"我將帶你走過安裝 MidnightBSD 的流程，如何添加一個圖形桌面環境，然後如何安裝應用程序。",-1)),i[34]||(i[34]=s("h3",{id:"安裝",tabindex:"-1"},[t("安裝 "),s("a",{class:"header-anchor",href:"#安裝","aria-label":"Permalink to “安裝”"},"​")],-1)),s("p",null,[i[9]||(i[9]=t("正如我所提到的，這是一個文本（ncurses）安裝過程，因此在這裏找不到可以用鼠標點擊的地方。相反，你將使用你鍵盤的 ",-1)),i[10]||(i[10]=s("code",null,"Tab",-1)),i[11]||(i[11]=t(" 鍵和箭頭鍵。在你下載",-1)),l(e,{href:"http://www.midnightbsd.org/download/"},{default:n(()=>[...i[7]||(i[7]=[t("最新的發佈版本",-1)])]),_:1}),i[12]||(i[12]=t("後，將它刻錄到一個 CD/DVD 或 USB 驅動器，並啓動你的機器（或者在 ",-1)),l(e,{href:"https://www.virtualbox.org/"},{default:n(()=>[...i[8]||(i[8]=[t("VirtualBox",-1)])]),_:1}),i[13]||(i[13]=t(" 中創建一個虛擬機）。安裝程序將打開並給你三個選項（圖 1）。使用你的鍵盤的箭頭鍵選擇 “Install”，並敲擊回車鍵。",-1))]),i[35]||(i[35]=r(`<p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_1.jpg" alt="MidnightBSD installer" title="MidnightBSD installer"></p><p><em>圖 1: 啓動 MidnightBSD 安裝程序。</em></p><p>在這裏要經歷相當多的屏幕。其中很多屏幕是一目瞭然的：</p><ol><li>設置非默認鍵盤映射（是/否）</li><li>設置主機名稱</li><li>添加可選系統組件（文檔、遊戲、32 位兼容性、系統源碼代碼）</li><li>對硬盤分區</li><li>管理員密碼</li><li>配置網絡接口</li><li>選擇地區（時區）</li><li>啓用服務（例如 ssh）</li><li>添加用户（圖 2）</li></ol><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_2.jpg" alt="Adding a user" title="Adding a user"></p><p><em>圖 2: 向系統添加一個用户。</em></p><p>在你向系統添加用户後，你將被進入到一個窗口中（圖 3），在這裏，你可以處理任何你可能忘記配置或你想重新配置的東西。如果你不需要作出任何更改，選擇 “Exit”，然後你的配置就會被應用。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/mightnight_3.jpg" alt="Applying your configurations" title="Applying your configurations"></p><p><em>圖 3: 應用你的配置。</em></p><p>在接下來的窗口中，當出現提示時，選擇 “No”，接下來系統將重啓。在 MidnightBSD 重啓後，你已經為下一階段的安裝做好了準備。</p><h3 id="後安裝階段" tabindex="-1">後安裝階段 <a class="header-anchor" href="#後安裝階段" aria-label="Permalink to “後安裝階段”">​</a></h3><p>當你最新安裝的 MidnightBSD 啓動時，你將發現你自己處於命令提示符當中。此刻，還沒有圖形界面。要安裝應用程序，MidnightBSD 依賴於 <code>mport</code> 工具。比如説你想安裝 Xfce 桌面環境。為此，登錄到 MidnightBSD 中，併發出下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport index</span></span>
<span class="line"><span>sudo mport install xorg</span></span></code></pre></div><p>你現在已經安裝好 Xorg 窗口服務器了，它允許你安裝桌面環境。使用命令來安裝 Xfce ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install xfce</span></span></code></pre></div><p>現在 Xfce 已經安裝好。不過，我們必須讓它同命令 <code>startx</code> 一起啓用。為此，讓我們先安裝 nano 編輯器。發出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install nano</span></span></code></pre></div><p>隨着 nano 安裝好，發出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano ~/.xinitrc</span></span></code></pre></div><p>這個文件僅包含一行內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exec startxfce4</span></span></code></pre></div><p>保存並關閉這個文件。如果你現在發出命令 <code>startx</code>, Xfce 桌面環境將會啓動。你應該會感到有點熟悉了吧（圖 4）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_4.jpg" alt=" Xfce" title="Xfce"></p><p><em>圖 4: Xfce 桌面界面已準備好服務。</em></p><p>因為你不會總是想必須發出命令 <code>startx</code>，你希望啓用登錄守護進程。然而，它卻沒有安裝。要安裝這個子系統，發出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install mlogind</span></span></code></pre></div><p>當完成安裝後，通過在 <code>/etc/rc.conf</code> 文件中添加一個項目來在啓動時啓用 mlogind。在 <code>rc.conf</code> 文件的底部，添加以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mlogind_enable=”YES”</span></span></code></pre></div><p>保存並關閉該文件。現在，當你啓動（或重啓）機器時，你應該會看到圖形登錄屏幕。在寫這篇文章的時候，在登錄後我最後得到一個空白屏幕和討厭的 X 光標。不幸的是，目前似乎並沒有這個問題的解決方法。所以，要訪問你的桌面環境，你必須使用 <code>startx</code> 命令。</p><h3 id="安裝應用" tabindex="-1">安裝應用 <a class="header-anchor" href="#安裝應用" aria-label="Permalink to “安裝應用”">​</a></h3><p>默認情況下，你找不到很多能可用的應用程序。如果你嘗試使用 <code>mport</code> 安裝應用程序，你很快就會感到沮喪，因為只能找到很少的應用程序。為解決這個問題，我們需要使用 <code>svnlite</code> 命令來查看檢出的可用 mport 軟件列表。回到終端窗口，併發出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>svnlite co http://svn.midnightbsd.org/svn/mports/trunk mports</span></span></code></pre></div><p>在你完成這些後，你應該看到一個命名為 <code>~/mports</code> 的新目錄。使用命令 <code>cd ~/.mports</code> 更改到這個目錄。發出 <code>ls</code> 命令，然後你應該看到許多的類別（圖 5）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_5.jpg" alt="applications" title="applications"></p><p><em>圖 5: mport 現在可用的應用程序類別。</em></p><p>你想安裝 Firefox 嗎？如果你查看 <code>www</code> 目錄，你將看到一個 <code>linux-firefox</code> 列表。發出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install linux-firefox</span></span></code></pre></div><p>現在你應該會在 Xfce 桌面菜單中看到一個 Firefox 項。翻找所有的類別，並使用 <code>mport</code> 命令來安裝你需要的所有軟件。</p><h3 id="一個悲哀的警告" tabindex="-1">一個悲哀的警告 <a class="header-anchor" href="#一個悲哀的警告" aria-label="Permalink to “一個悲哀的警告”">​</a></h3><p>一個悲哀的小警告是，<code>mport</code> （通過 <code>svnlite</code>）僅能找到的一個辦公套件的版本是 OpenOffice 3 。那是非常過時的。儘管在 <code>~/mports/editors</code> 目錄中能找到 Abiword ，但是它看起來不能安裝。甚至在安裝 OpenOffice 3 後，它會輸出一個執行格式錯誤。換句話説，你不能使用 MidnightBSD 在辦公生產效率方面做很多的事情。但是，嘿嘿，如果你周圍正好有一箇舊的 Palm Pilot，你可以安裝 pilot-link。換句話説，可用的軟件不足以構成一個極其有用的桌面發行版……至少對普通用户不是。但是，如果你想在 MidnightBSD 上開發，你將找到很多可用的工具可以安裝（查看 <code>~/mports/devel</code> 目錄）。你甚至可以使用命令安裝 Drupal ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install drupal7</span></span></code></pre></div><p>當然，在此之後，你將需要創建一個數據庫（MySQL 已經安裝）、安裝 Apache（<code>sudo mport install apache24</code>），並配置必要的 Apache 配置。</p><p>顯然地，已安裝的和可以安裝的是一個應用程序、系統和服務的大雜燴。但是隨着足夠多的工作，你最終可以得到一個能夠服務於特殊目的的發行版。</p><h3 id="享受-bsd-優良" tabindex="-1">享受 *BSD 優良 <a class="header-anchor" href="#享受-bsd-優良" aria-label="Permalink to “享受 *BSD 優良”">​</a></h3><p>這就是如何使 MidnightBSD 啓動，並使其運行某種有用的桌面發行版的方法。它不像很多其它的 Linux 發行版一樣快速簡便，但是如果你想要一個促使你思考的發行版，這可能正是你正在尋找的。儘管大多數競爭對手都準備了很多可以安裝的應用軟件，但 MidnightBSD 無疑是一個 Linux 愛好者或管理員應該嘗試的有趣挑戰。</p><hr>`,46)),s("p",null,[i[15]||(i[15]=t("via: ",-1)),l(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/5/midnightbsd-could-be-your-gateway-freebsd"},{default:n(()=>[...i[14]||(i[14]=[t("https://www.linux.com/learn/intro-to-linux/2018/5/midnightbsd-could-be-your-gateway-freebsd",-1)])]),_:1})]),s("p",null,[i[20]||(i[20]=t("作者：",-1)),l(e,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...i[16]||(i[16]=[t("Jack Wallen",-1)])]),_:1}),i[21]||(i[21]=t(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[17]||(i[17]=[t("lujun9972",-1)])]),_:1}),i[22]||(i[22]=t(" 譯者：",-1)),l(e,{href:"https://github.com/robsean"},{default:n(()=>[...i[18]||(i[18]=[t("robsean",-1)])]),_:1}),i[23]||(i[23]=t(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:n(()=>[...i[19]||(i[19]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[26]||(i[26]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[24]||(i[24]=[t("LCTT",-1)])]),_:1}),i[27]||(i[27]=t(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:n(()=>[...i[25]||(i[25]=[t("Linux中國",-1)])]),_:1}),i[28]||(i[28]=t(" 榮譽推出",-1))])])}const S=a(g,[["render",h]]);export{D as __pageData,S as default};
